// Mooring solver: analytical benchmarks and comparison with MoorPy 1.3.0
// (independent implementation; reference values generated by
// scripts/mooring-reference.py into tests/fixtures/moorpy-reference.json).

import { test } from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import { catenaryShape, solveCatenary, type CatenaryResult } from '../../../studio/src/core/mooring/catenary.ts';
import { lineTypeFromMaterial } from '../../../studio/src/core/mooring/library.ts';
import {
  circularLayout, lengthForPretension, solveEquilibrium, solveLines, stiffness, mooringLoad,
  type MooringSystem, type Pose,
} from '../../../studio/src/core/mooring/system.ts';

const ref = JSON.parse(fs.readFileSync(new URL('../../fixtures/moorpy-reference.json', import.meta.url), 'utf8'));
const rel = (a: number, b: number) => Math.abs(a - b) / Math.max(Math.abs(b), 1e-300);

function ok(r: ReturnType<typeof solveCatenary>): CatenaryResult {
  assert.equal(r.ok, true, r.ok ? '' : r.message);
  return r as CatenaryResult;
}

test('line properties equal MoorPy getLineProps for 6 materials × 3 diameters (1e-12)', () => {
  for (const p of ref.lineProps) {
    const t = lineTypeFromMaterial(p.material, p.dnommm / 1000);
    for (const k of ['mass', 'w', 'EA', 'MBL'] as const) {
      assert.ok(rel(t[k], p[k]) < 1e-12, `${p.material} ${p.dnommm} ${k}: ${t[k]} vs ${p[k]}`);
    }
  }
});

test('single-line catenary equals MoorPy (suspended, seabed contact, nearly slack)', () => {
  for (const c of ref.catenary) {
    const r = ok(solveCatenary(c.XF, c.ZF, { L: c.L, EA: c.EA, w: c.w }));
    // MoorPy converges to an absolute displacement tolerance of 1e-10 m; tensions agree to ~1e-8
    assert.ok(rel(r.HF, c.HF) < 1e-6, `HF ${c.XF},${c.ZF},${c.L}: ${r.HF} vs ${c.HF}`);
    assert.ok(rel(r.VF, c.VF) < 1e-6, `VF ${c.XF},${c.ZF},${c.L}: ${r.VF} vs ${c.VF}`);
    assert.ok(Math.abs(r.LB - c.LBot) < 1e-4 * c.L, `LB ${r.LB} vs ${c.LBot}`);
    assert.ok(rel(r.VA, c.VA) < 1e-6 || Math.abs(r.VA - c.VA) < 1e-6 * c.VF, `VA ${r.VA} vs ${c.VA}`);
  }
});

test('analytical limit: an almost inextensible fully suspended line follows the classical catenary', () => {
  // parabola-free check: for EA -> inf, x(s) and z(s) satisfy cosh relation z + c0 = c cosh((x + x0)/c), c = H/w
  const p = { L: 500, EA: 1e16, w: 1000 };
  const r = ok(solveCatenary(460, 190, p));
  assert.equal(r.regime, 'suspended');
  const c = r.HF / p.w;
  const pts = catenaryShape(r, p, 50);
  const a0 = Math.asinh(r.VA / r.HF);
  for (const [x, z] of pts) {
    const zc = c * (Math.cosh(x / c + a0) - Math.cosh(a0));
    assert.ok(Math.abs(z - zc) < 1e-6, `x=${x}: ${z} vs ${zc}`);
  }
  // the shape ends at the fairlead
  const [xe, ze] = pts[pts.length - 1];
  assert.ok(Math.abs(xe - 460) < 1e-6 && Math.abs(ze - 190) < 1e-6);
});

test('elastic shape closes at the fairlead and the grounded part lies on the seabed', () => {
  const t = lineTypeFromMaterial('chain', 0.12);
  for (const [XF, ZF, L] of [[800, 250, 900], [850, 250, 880], [300, 200, 400]]) {
    const r = ok(solveCatenary(XF, ZF, { L, EA: t.EA, w: t.w }));
    const pts = catenaryShape(r, { L, EA: t.EA, w: t.w }, 200);
    const [xe, ze] = pts[pts.length - 1];
    assert.ok(Math.abs(xe - XF) < 1e-6 * XF && Math.abs(ze - ZF) < 1e-6 * XF, `${XF},${ZF}: ${xe},${ze}`);
    for (const [x, z] of pts) if (x < r.touchdownX - 1e-9) assert.ok(Math.abs(z) < 1e-9);
  }
});

test('slack and vertical lines: zero horizontal tension, hanging weight carried at the fairlead', () => {
  const p = { L: 900, EA: 1e9, w: 2000 };
  const slack = ok(solveCatenary(600, 250, p));
  assert.equal(slack.regime, 'slack');
  assert.equal(slack.HF, 0);
  assert.ok(rel(slack.VF, p.w * slack.suspended) < 1e-12);
  // stretched hanging length: s + w s^2 / (2 EA) = ZF
  assert.ok(Math.abs(slack.suspended + (p.w * slack.suspended ** 2) / (2 * p.EA) - 250) < 1e-9);
  const tendon = ok(solveCatenary(0, 300, { L: 299, EA: 1e9, w: 500 }));
  assert.equal(tendon.regime, 'vertical');
  // taut vertical: ZF = L + (V L - w L^2 / 2)/EA
  assert.ok(Math.abs(299 + (tendon.VF * 299 - (500 * 299 * 299) / 2) / 1e9 - 300) < 1e-9);
});

test('invalid inputs are refused, never "solved"', () => {
  const bad: Array<[number, number, { L: number; EA: number; w: number }]> = [
    [100, -5, { L: 200, EA: 1e9, w: 100 }],
    [100, 50, { L: 200, EA: 1e9, w: -10 }],
    [100, 50, { L: 0, EA: 1e9, w: 100 }],
    [Number.NaN, 50, { L: 200, EA: 1e9, w: 100 }],
  ];
  for (const [x, z, p] of bad) assert.equal(solveCatenary(x, z, p).ok, false);
});

function oc3(): MooringSystem {
  const s = ref.spread3;
  const { anchors, fairleads } = circularLayout(3, s.anchorRadius, s.fairleadRadius, s.fairleadZ, s.depth, 180);
  return {
    depth: s.depth,
    lineTypes: [{ id: 'oc3', name: 'OC3', material: 'chain', d: 0.09, mass: 0, w: s.w, EA: s.EA, MBL: 1e8, Cd: 1, Ca: 1, source: s.source }],
    anchors, fairleads,
    lines: [0, 1, 2].map((i) => ({ id: `L${i + 1}`, name: `Line ${i + 1}`, anchorId: anchors[i].id, fairleadId: fairleads[i].id, lineTypeId: 'oc3', length: s.length })),
  };
}

test('3-line spread: forces and moments on the platform equal MoorPy at 7 poses', () => {
  const sys = oc3();
  for (const c of ref.spread3.cases) {
    const pose = c.pose as Pose;
    const lines = solveLines(sys, pose);
    assert.ok(lines.every((l) => l.ok));
    const f = mooringLoad(lines, pose);
    const scaleF = Math.max(...c.force.slice(0, 3).map(Math.abs));
    const scaleM = Math.max(...c.force.slice(3).map(Math.abs), scaleF * 5.2);
    for (let i = 0; i < 6; i++) {
      const tolAbs = (i < 3 ? scaleF : scaleM) * 1e-6;
      assert.ok(Math.abs(f[i] - c.force[i]) < tolAbs, `pose ${pose} dof ${i}: ${f[i]} vs ${c.force[i]}`);
    }
    // fairlead tensions (MoorPy line order equals ours)
    lines.forEach((l, i) => assert.ok(rel(l.cat!.TF, c.fairleadTension[i]) < 1e-6));
  }
});

test('zero external load: the symmetric system returns to its neutral position', () => {
  const sys = oc3();
  const eq = solveEquilibrium(sys, { pose: [15, -10, 0, 0, 0, 0.08] });
  assert.equal(eq.ok, true, eq.message);
  assert.ok(Math.hypot(eq.pose[0], eq.pose[1]) < 1e-4 && Math.abs(eq.pose[5]) < 1e-7, `${eq.pose}`);
});

test('steady external load: equilibrium offset balances it; residual is tiny', () => {
  const sys = oc3();
  const Fx = 1.0e6;
  const eq = solveEquilibrium(sys, { external: [Fx, 0, 0] });
  assert.equal(eq.ok, true, eq.message);
  assert.ok(eq.pose[0] > 0, 'drifts downstream');
  assert.ok(Math.abs(eq.load[0] + Fx) < 1e-6 * Fx * 10);
  assert.ok(Math.abs(eq.pose[1]) < 1e-6 && Math.abs(eq.pose[5]) < 1e-9, 'no sway or yaw for a load along a symmetry axis');
});

test('small-displacement stiffness: single line equals the catenary end stiffness of MoorPy', () => {
  const c = ref.catenary[0];
  const sys: MooringSystem = {
    depth: c.ZF,
    lineTypes: [{ id: 't', name: 't', material: 'chain', d: 0.1, mass: 0, w: c.w, EA: c.EA, MBL: 1e9, Cd: 1, Ca: 1, source: 'test' }],
    anchors: [{ id: 'A', name: 'A', x: -c.XF, y: 0, z: -c.ZF, type: 'drag' }],
    fairleads: [{ id: 'F', name: 'F', x: 0, y: 0, z: 0 }],
    lines: [{ id: 'L', name: 'L', anchorId: 'A', fairleadId: 'F', lineTypeId: 't', length: c.L }],
  };
  const K = stiffness(sys, [0, 0, 0, 0, 0, 0])!;
  // MoorPy stiffnessB is [[dH/dx, dH/dz], [dV/dx, dV/dz]] for the fairlead end
  assert.ok(rel(K[0][0], c.stiffnessB[0][0]) < 1e-4, `Kxx ${K[0][0]} vs ${c.stiffnessB[0][0]}`);
  assert.ok(rel(K[2][2], c.stiffnessB[1][1]) < 1e-4, `Kzz ${K[2][2]} vs ${c.stiffnessB[1][1]}`);
  // transverse stiffness of a single line: H / XF (rotation of the line plane)
  const r = ok(solveCatenary(c.XF, c.ZF, { L: c.L, EA: c.EA, w: c.w }));
  assert.ok(rel(K[1][1], r.HF / c.XF) < 1e-4);
});

test('rotating the whole layout rotates the forces and leaves the tensions unchanged', () => {
  const a = oc3();
  const b = oc3();
  const th = 0.7;
  const rot = (x: number, y: number) => [x * Math.cos(th) - y * Math.sin(th), x * Math.sin(th) + y * Math.cos(th)];
  b.anchors = b.anchors.map((p) => { const [x, y] = rot(p.x, p.y); return { ...p, x, y }; });
  b.fairleads = b.fairleads.map((p) => { const [x, y] = rot(p.x, p.y); return { ...p, x, y }; });
  const [ox, oy] = rot(12, -4);
  const fa = mooringLoad(solveLines(a, [12, -4, 0, 0, 0, 0]), [12, -4, 0, 0, 0, 0]);
  const pb: Pose = [ox, oy, 0, 0, 0, 0];
  const fb = mooringLoad(solveLines(b, pb), pb);
  const [rx, ry] = rot(fa[0], fa[1]);
  assert.ok(Math.abs(fb[0] - rx) < 1e-6 * Math.abs(fa[0]) && Math.abs(fb[1] - ry) < 1e-6 * Math.abs(fa[0]));
  assert.ok(Math.abs(fb[2] - fa[2]) < 1e-6 * Math.abs(fa[2]));
  assert.ok(Math.abs(fb[5] - fa[5]) < 1e-6 * Math.max(1, Math.abs(fa[5])));
});

test('one-line failure: the platform drifts away from the failed line and still finds equilibrium', () => {
  const sys = oc3();
  sys.lines[0].failed = true; // line at 180°
  const eq = solveEquilibrium(sys);
  assert.equal(eq.ok, true, eq.message);
  assert.ok(eq.pose[0] > 1, `drifts towards +x: ${eq.pose[0]}`);
  assert.equal(eq.lines.length, 2);
});

test('impossible demand is reported, not "converged": load beyond what the lines can resist', () => {
  const sys = oc3();
  const eq = solveEquilibrium(sys, { external: [5e9, 0, 0] });
  assert.equal(eq.ok, false);
  assert.match(eq.message ?? '', /breaking load|not found/);
  const none = solveEquilibrium({ ...sys, lines: sys.lines.map((l) => ({ ...l, failed: true })) });
  assert.equal(none.ok, false);
});

test('pretension: the length found reproduces the target fairlead tension', () => {
  const t = lineTypeFromMaterial('chain', 0.12);
  const target = 1.5e6;
  const r = lengthForPretension(800, 250, t, target);
  assert.equal(r.ok, true);
  const c = ok(solveCatenary(800, 250, { L: (r as { length: number }).length, EA: t.EA, w: t.w }));
  assert.ok(rel(c.TF, target) < 1e-6);
  assert.equal(lengthForPretension(800, 250, t, 1).ok, false, 'below the hanging weight: infeasible');
});

import { runSafetyStudy, DEFAULT_CRITERIA } from '../../../studio/src/core/mooring/safety.ts';

test('safety study: intact + one case per failed line; critical line is the one resisting the load', () => {
  const sys = oc3();
  sys.lineTypes[0] = { ...sys.lineTypes[0], MBL: 8e6 };
  const cases = runSafetyStudy(sys, [8e5, 0, 0]);
  assert.equal(cases.length, 4);
  const intact = cases[0];
  assert.equal(intact.label, 'Intact');
  assert.equal(intact.equilibrium.ok, true);
  assert.equal(intact.criticalLineId, 'L1', 'the line anchored upstream (180°) carries the load');
  assert.ok(intact.minSF > 0 && Number.isFinite(intact.minSF));
  for (const c of cases.slice(1)) {
    assert.equal(c.criterion, DEFAULT_CRITERIA.damagedSF);
    assert.equal(c.lines.length, 2);
  }
  // losing the loaded line gives the largest offset
  const worst = cases.slice(1).reduce((a, b) => (b.offset > a.offset ? b : a));
  assert.equal(worst.failedLineId, 'L1');
  // a case is marked as failing when its minimum SF is below the criterion
  for (const c of cases) if (c.equilibrium.ok && c.minSF < c.criterion) assert.equal(c.pass, false);
});

test('drifting past the remaining anchors is reported as lost station keeping, never as a pass', () => {
  const sys = oc3();
  sys.lineTypes[0] = { ...sys.lineTypes[0], MBL: 5e7 };
  // load towards +x: losing the upstream line leaves only lines anchored downstream
  const cases = runSafetyStudy(sys, [3e5, 0, 0]);
  const lost = cases.find((c) => c.failedLineId === 'L1')!;
  if (lost.equilibrium.ok) {
    assert.equal(lost.pass, false);
    assert.ok(lost.messages.some((m) => /Station keeping lost/.test(m)), lost.messages.join(' '));
  }
  // an offset limit, when given, is enforced
  const limited = runSafetyStudy(sys, [3e5, 0, 0], { ...DEFAULT_CRITERIA, maxOffset: 1 });
  assert.equal(limited[0].pass, limited[0].offset <= 1);
});

test('example project: full study runs, pretension is reproduced and the lost-station case fails', async () => {
  const { createExampleProject, EXAMPLE } = await import('../../../studio/src/core/example.ts');
  const { runMooringAnalysis } = await import('../../../studio/src/core/mooring/run.ts');
  const { parseProject, serializeProject } = await import('../../../studio/src/core/project.ts');
  const p = createExampleProject();
  assert.deepEqual(parseProject(serializeProject(p)), p);
  const neutral = runMooringAnalysis(p.mooring, p.environment.h)!;
  assert.equal(neutral.ok, true, neutral.status);
  assert.ok((neutral.offset ?? 1) < 1e-6);
  // length is stored rounded to 1 mm, which moves the tension by ~2e-5
  for (const l of neutral.lines) assert.ok(rel(l.TF, EXAMPLE.pretension) < 1e-4, `${l.name} TF ${l.TF}`);
  const loaded = runMooringAnalysis({ ...p.mooring!, external: [4e5, 0, 0] }, p.environment.h)!;
  assert.equal(loaded.ok, true);
  assert.ok(loaded.cases.find((c) => c.id === 'intact')!.pass);
  assert.equal(loaded.cases.find((c) => c.failedLineId === 'L1')!.pass, false);
  assert.match(loaded.status, /do not meet the criteria: Line 1 failed/);
  assert.ok(loaded.sweep && loaded.sweep.offsets.length === 25);
});
